name: Shurik
run-name: ${{ github.event_name == 'schedule' && 'Shurik recovery' || (inputs.command == 'iterate' && format('Shurik {0} / {1}', inputs.loop_id, inputs.iteration) || format('Shurik {0} / {1}', inputs.loop_id, inputs.command)) }}
on:
  schedule:
    - cron: '*/15 * * * *'
  workflow_dispatch:
    inputs:
      command:
        description: Start a loop or swarm, stop/resume a member; iterate is internal
        required: true
        type: choice
        options: [start, stop, resume, iterate]
        default: start
      loop_id:
        description: Loop ID, or swarm prefix on start; stop/resume use individual IDs
        required: true
        type: string
      model:
        description: 'JSON model: {"provider":"opencode-go","name":"minimax-m3.1-flash-free","reasoning":"high"}; optional overrides on resume'
        type: string
      swarm:
        description: 'Start-only JSON: {"agents":4} or {"models":[...]} with optional shared model'
        type: string
      create_pr:
        description: Create draft PRs when allowed (auto), always try (true), or disable (false)
        type: choice
        options: [auto, 'true', 'false']
        default: 'false'
      source_ref:
        description: Source for a new task branch; existing branches use their current tip
        type: string
      work-seconds:
        description: Work budget per iteration, 10–1800; Shurik defaults to 1800 on start
        type: string
      wait-seconds:
        description: Idle seconds between iterations; thirty minutes by default
        type: string
        default: '1800'
      checkpoint-seconds:
        description: Checkpoint interval, 1–1800; Shurik defaults to 300 on start
        type: string
      checkpoint-paths:
        description: JSON array of ignored task paths; Shurik defaults to an empty array
        type: string
      prompt:
        description: Relative task prompt path; Shurik defaults to PROMPT.md on start
        type: string
      deadline:
        description: Optional absolute UTC deadline for start/resume
        type: string
      generation:
        description: Internal continuation generation
        default: '1'
        type: string
      iteration:
        description: Continuous iteration number across resumes
        default: '1'
        type: string
permissions:
  contents: write
  pull-requests: write
  actions: write
jobs:
  control:
    if: github.event_name == 'workflow_dispatch' && inputs.command != 'iterate' && github.ref == format('refs/heads/{0}', github.event.repository.default_branch)
    runs-on: ubuntu-24.04
    timeout-minutes: 10
    concurrency:
      group: shurik-control-${{ inputs.loop_id }}
      cancel-in-progress: false
    steps:
      - uses: actions/checkout@d23441a48e516b6c34aea4fa41551a30e30af803 # v6
        with:
          persist-credentials: false
          fetch-depth: 0
      - id: shurik
        uses: igor-makarov/shurik@v2
        with:
          inputs: ${{ toJSON(inputs) }}
      - name: Preserve emergency snapshot after publication failure
        if: failure()
        uses: actions/upload-artifact@ea165f8d65b6e75b540449e92b4886f43607fa02 # v4
        with:
          name: shurik-emergency-${{ github.run_id }}
          path: ${{ steps.shurik.outputs.emergency-path }}
          include-hidden-files: true
          if-no-files-found: ignore
          retention-days: 7
  iteration:
    if: github.event_name == 'workflow_dispatch' && inputs.command == 'iterate' && github.ref == format('refs/heads/{0}', github.event.repository.default_branch)
    runs-on: ubuntu-24.04
    timeout-minutes: 60
    concurrency:
      group: shurik-worker-${{ inputs.loop_id }}
      cancel-in-progress: false
    steps:
      - uses: actions/checkout@d23441a48e516b6c34aea4fa41551a30e30af803 # v6
        with:
          persist-credentials: false
          fetch-depth: 0
      - id: shurik
        uses: igor-makarov/shurik@v2
        env:
          OPENCODE_API_KEY: ${{ secrets.OPENCODE_API_KEY }}
        with:
          command: iterate
          inputs: ${{ toJSON(inputs) }}
      - name: Preserve emergency snapshot after publication failure
        if: failure()
        uses: actions/upload-artifact@ea165f8d65b6e75b540449e92b4886f43607fa02 # v4
        with:
          name: shurik-emergency-${{ github.run_id }}
          path: ${{ steps.shurik.outputs.emergency-path }}
          include-hidden-files: true
          if-no-files-found: ignore
          retention-days: 7
  recovery:
    needs: [control, iteration]
    if: always() && github.ref == format('refs/heads/{0}', github.event.repository.default_branch)
    runs-on: ubuntu-24.04
    timeout-minutes: 40
    permissions:
      contents: write
      actions: write
    steps:
      - uses: actions/checkout@d23441a48e516b6c34aea4fa41551a30e30af803 # v6
        with:
          persist-credentials: false
          fetch-depth: 0
      - uses: igor-makarov/shurik@v2
        env:
          SHURIK_ITERATION_RESULT: ${{ needs.iteration.result }}
        with:
          command: recover
      - name: Wait for this loop's next iteration
        id: wait
        if: github.event_name == 'workflow_dispatch' && inputs.command == 'iterate' && needs.iteration.result != 'skipped'
        env:
          GH_TOKEN: ${{ github.token }}
          GH_REPO: ${{ github.repository }}
          SHURIK_WAIT_LOOP_ID: ${{ inputs.loop_id }}
          SHURIK_WAIT_GENERATION: ${{ inputs.generation }}
          SHURIK_WAIT_ITERATION: ${{ inputs.iteration }}
        run: node .github/scripts/wait-for-shurik.cjs
      - name: Recover after the saved wait
        if: steps.wait.outputs.ready == 'true'
        uses: igor-makarov/shurik@v2
        env:
          SHURIK_ITERATION_RESULT: ${{ needs.iteration.result }}
        with:
          command: recover
=== wait script ===
const { execFileSync } = require('node:child_process');
const { appendFileSync } = require('node:fs');

function waitState(control, expected, now) {
  if (control.id !== expected.id || control.generation !== expected.generation ||
      control.next !== expected.iteration + 1 || control.status !== 'running' ||
      control.owner || !control.nextRunAt) return { kind: 'skip' };

  const due = Date.parse(control.nextRunAt);
  const deadline = control.deadline ? Date.parse(control.deadline) : Infinity;
  if (!Number.isFinite(due) || Number.isNaN(deadline)) throw new Error('Invalid loop timing');
  if (now >= deadline) return { kind: 'skip' };
  if (now >= due) return { kind: 'ready' };
  return { kind: 'wait', until: Math.min(due, deadline) };
}

async function waitForNextIteration({ readControl, expected, now = Date.now,
  sleep = ms => new Promise(resolve => setTimeout(resolve, ms)), report = console.log }) {
  let errors = 0;
  let lastDue;
  for (;;) {
    let control;
    try {
      control = await readControl();
      errors = 0;
    } catch (error) {
      if (++errors >= 5) throw new Error('Cannot read loop control after five attempts', { cause: error });
      report('Control read failed; retrying in one minute.');
      await sleep(60_000);
      continue;
    }
    const decision = waitState(control, expected, now());
    if (decision.kind !== 'wait') return decision.kind === 'ready';
    if (lastDue !== decision.until) {
      report(`Waiting for ${expected.id} until ${new Date(decision.until).toISOString()}`);
      lastDue = decision.until;
    }
    await sleep(Math.max(1, Math.min(60_000, decision.until - now())));
  }
}

function readControl(repo, id, request = execFileSync) {
  const path = `repos/${repo}/contents/control.json?ref=${encodeURIComponent(`shurik-control/${id}`)}`;
  const response = JSON.parse(request('gh', ['api', path], {
    encoding: 'utf8', timeout: 30_000, stdio: ['ignore', 'pipe', 'pipe'],
  }));
  if (response.encoding !== 'base64' || typeof response.content !== 'string') {
    throw new Error('Expected a control JSON file');
  }
  return JSON.parse(Buffer.from(response.content, 'base64').toString('utf8'));
}

async function main() {
  const expected = { id: process.env.SHURIK_WAIT_LOOP_ID,
    generation: Number(process.env.SHURIK_WAIT_GENERATION),
    iteration: Number(process.env.SHURIK_WAIT_ITERATION) };
  if (!expected.id || !Number.isSafeInteger(expected.generation) || expected.generation < 1 ||
      !Number.isSafeInteger(expected.iteration) || expected.iteration < 1) {
    throw new Error('Expected an iteration loop ID, generation, and sequence');
  }
  const ready = await waitForNextIteration({ expected,
    readControl: () => readControl(process.env.GH_REPO, expected.id) });
  appendFileSync(process.env.GITHUB_OUTPUT, `ready=${ready}\n`);
  console.log(ready ? 'Saved wait has elapsed; invoking native recovery.' : 'Wait no longer belongs to this iteration.');
}

module.exports = { waitState, waitForNextIteration, readControl };
if (require.main === module) main().catch(error => { console.error(error.message); process.exitCode = 1; });
